"""
Static assets embedded as base64 so the app has no external file
dependency — a single self-contained module works the same whether run
locally or on Streamlit Community Cloud, with no assets/ folder to
remember to commit.
"""

LBS_LOGO_B64 = ""


def crest_svg(size=140):
    """LBS Olympics Championship crest — a Wimbledon-style circular emblem
    (orange ring, beige face, curved text top/bottom, crossed rackets and
    a shuttlecock at center) in the app's own beige/orange palette rather
    than tennis green/purple. Text-on-a-circle is done with two SVG
    <textPath> arcs: both paths run left-to-right (start point on the left,
    end point on the right) so the glyphs stay upright in both — the top
    arc bows upward (sweep-flag 1) and the bottom arc bows downward
    (sweep-flag 0).

    Deliberately built as ONE unbroken line with no blank lines anywhere in
    the string: Streamlit's st.markdown runs raw HTML through a CommonMark
    parser even with unsafe_allow_html=True, and a blank line inside a
    multi-line HTML block ends that block early — the tail of the SVG
    (the <text>/<textPath> elements) was falling through as literal
    markdown text next to an empty circle instead of rendering inside it."""
    return (
        f'<svg width="{size}" height="{size}" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">'
        '<defs><linearGradient id="crestRingGrad" x1="0%" y1="0%" x2="100%" y2="100%">'
        '<stop offset="0%" stop-color="#e2984a"/><stop offset="100%" stop-color="#b3661c"/>'
        '</linearGradient></defs>'
        '<circle cx="100" cy="100" r="97" fill="url(#crestRingGrad)" stroke="#8a4d13" stroke-width="2"/>'
        '<circle cx="100" cy="100" r="78" fill="#f3e9d2" stroke="#c98a3e" stroke-width="2"/>'
        '<path id="crestTopArc" d="M 24,100 A 76,76 0 0 1 176,100" fill="none"/>'
        '<path id="crestBottomArc" d="M 24,100 A 76,76 0 0 0 176,100" fill="none"/>'
        '<text font-family="\'DM Mono\', monospace" font-size="15" font-weight="700" letter-spacing="2.5" fill="#fdf3e4">'
        '<textPath href="#crestTopArc" startOffset="50%" text-anchor="middle">LBS OLYMPICS</textPath></text>'
        '<text font-family="\'DM Mono\', monospace" font-size="15" font-weight="700" letter-spacing="3.5" fill="#fdf3e4">'
        '<textPath href="#crestBottomArc" startOffset="50%" text-anchor="middle">CHAMPIONSHIP</textPath></text>'
        '<text x="24" y="106" font-size="14" fill="#fdf3e4" text-anchor="middle">&#9733;</text>'
        '<text x="176" y="106" font-size="14" fill="#fdf3e4" text-anchor="middle">&#9733;</text>'
        '<g transform="translate(100,102)">'
        '<g transform="rotate(-40)">'
        '<rect x="-4.5" y="4" width="9" height="36" rx="4.5" fill="#3a2a15"/>'
        '<ellipse cx="0" cy="-17" rx="17" ry="22" fill="none" stroke="#3a2a15" stroke-width="6"/></g>'
        '<g transform="rotate(40)">'
        '<rect x="-4.5" y="4" width="9" height="36" rx="4.5" fill="#3a2a15"/>'
        '<ellipse cx="0" cy="-17" rx="17" ry="22" fill="none" stroke="#3a2a15" stroke-width="6"/></g>'
        '<circle cx="0" cy="0" r="7" fill="#d97706" stroke="#3a2a15" stroke-width="1.5"/>'
        '</g></svg>'
    )